import React, { useState } from 'react';

const Home = () => {
  // Base de données plate - Gardée ultra simple pour tes modifications en direct
  const [courses, setCourses] = useState([
    { id: 1, title: "Hacking Éthique & Pentest : Les Fondations", level: "Débutant", price: 25000, isFree: false },
    { id: 2, title: "Sécurisation des Architectures Réseaux & pfSense", level: "Avancé", price: 40000, isFree: false },
    { id: 3, title: "Introduction à la Cybersécurité et Hygiène Numérique", level: "Débutant", price: 0, isFree: true }
  ]);

  // États de l'application
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  const handlePayment = (e) => {
    e.preventDefault();
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setPaymentSuccess(true);
    }, 2500);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 font-sans antialiased selection:bg-blue-500/20 selection:text-blue-200">
      
      {/* 1. NAVIGATION ULTRA-FUTURISTE (Bordures chirurgicales et flou de verre) */}
      <header className="border-b border-slate-900 bg-[#020617]/70 backdrop-blur-xl px-8 py-4 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-3 group cursor-pointer">
          <div className="relative">
            <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-cyan-600 rounded-lg blur opacity-40 group-hover:opacity-75 transition duration-500"></div>
            <div className="relative bg-slate-950 text-white font-black px-3 py-1 rounded-lg text-sm border border-slate-800">
              A
            </div>
          </div>
          <span className="text-sm font-semibold tracking-[0.2em] text-white uppercase">
            Avalon <span className="text-blue-500 font-light text-slate-400">Secure</span>
          </span>
        </div>

        {/* Barre de recherche intégrée d'expert (S'élargit subtilement au focus) */}
        <div className="flex items-center gap-6">
          <div className={`relative flex items-center bg-slate-950/60 border rounded-full px-4 py-1.5 transition-all duration-300 ${isSearchFocused ? 'border-blue-500/50 w-64 shadow-[0_0_15px_rgba(59,130,246,0.1)]' : 'border-slate-800/80 w-48'}`}>
            <input
              type="text"
              placeholder="Recherche système..."
              value={searchQuery}
              onFocus={() => setIsSearchFocused(true)}
              onBlur={() => setIsSearchFocused(false)}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent border-none text-xs text-slate-300 focus:outline-none w-full font-mono placeholder:text-slate-600"
            />
            <span className="text-slate-600 text-xs font-mono pointer-events-none">/</span>
          </div>

          <a href="/login" className="text-slate-400 hover:text-white text-xs font-medium tracking-wider uppercase transition">
            Connexion
          </a>
          
          <a href="/register" className="relative group overflow-hidden bg-white text-slate-950 px-5 py-2 rounded-lg text-xs font-bold tracking-wider uppercase transition-all duration-300 hover:scale-[1.02]">
            <span className="relative z-10">Rejoindre</span>
          </a>
        </div>
      </header>

      {/* 2. ZONE HÉRO CENTRALE (Minimalisme haut de gamme, focus absolu sur l'action) */}
      <section className="relative min-h-[75vh] flex flex-col justify-center items-center px-4 overflow-hidden border-b border-slate-900/50">
        {/* Grille de fond matrix/cyber */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#0f172a_1px,transparent_1px),linear-gradient(to_bottom,#0f172a_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_50%,#000_70%,transparent_100%)] opacity-25"></div>
        {/* Halo de fusion quantique en arrière-plan */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[350px] bg-gradient-to-r from-blue-500/10 to-cyan-500/5 blur-[140px] rounded-full pointer-events-none"></div>

        <div className="max-w-4xl mx-auto text-center relative z-10 space-y-8">
          
          <div className="inline-flex items-center gap-2.5 bg-slate-950/80 border border-slate-800 px-4 py-1.5 rounded-full shadow-2xl">
            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full shadow-[0_0_8px_#3b82f6]"></div>
            <span className="text-[10px] font-mono tracking-[0.15em] text-slate-400 uppercase">Écosystème Académique International</span>
          </div>

          <h2 className="text-4xl md:text-6xl font-black tracking-tight text-white leading-[1.1] font-sans">
            Déployez vos compétences <br />
            d'élite avec <br />
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-white via-slate-200 to-blue-500 drop-shadow-sm">
              AVALON SECURE ACADEMY
            </span>
          </h2>

          <p className="text-slate-400 max-w-2xl mx-auto text-xs md:text-sm font-light leading-relaxed tracking-wide">
            Accédez à un contenu d'ingénierie réseau et de cyberdéfense de classe mondiale. <br />
            Validez nos parcours fondamentaux gratuits et accédez aux modules avancés de niveau expert.
          </p>

          {/* L'Appel à l'Action Principal au Centre */}
          <div className="pt-4">
            <a href="/register" className="relative inline-flex group items-center justify-center p-0.5 overflow-hidden text-xs font-bold tracking-widest text-white uppercase rounded-lg group">
              <span className="absolute inset-0 w-full h-full bg-gradient-to-br from-blue-600 to-cyan-600 group-hover:from-cyan-500 group-hover:to-blue-500 transition-all duration-500 rounded-lg"></span>
              <span className="relative px-8 py-4 transition-all ease-in duration-200 bg-slate-950 rounded-lg group-hover:bg-opacity-0 font-mono">
                Explorer les cours
              </span>
            </a>
          </div>

        </div>
      </section>

      {/* 3. CARTES DE COURS PREMIUM */}
      <section id="courses" className="max-w-6xl mx-auto px-8 py-20">
        <div className="flex justify-between items-center mb-12">
          <div className="space-y-1">
            <span className="text-[10px] font-mono text-blue-500 tracking-[0.2em] uppercase block">Catalogue</span>
            <h3 className="text-lg font-bold text-white tracking-wide uppercase">Formations Disponibles</h3>
          </div>
          <div className="h-px bg-slate-900 flex-1 mx-8 hidden md:block"></div>
        </div>
        
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {courses
            .filter(c => c.title.toLowerCase().includes(searchQuery.toLowerCase()))
            .map((course) => (
              <div key={course.id} className="group bg-slate-950/40 border border-slate-900 rounded-xl p-6 flex flex-col justify-between transition-all duration-300 hover:border-slate-800 hover:bg-slate-950/80 shadow-xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-blue-500/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                
                <div>
                  <div className="flex justify-between items-center mb-6">
                    <span className="bg-slate-900 border border-slate-800 text-blue-400 text-[10px] font-mono px-2.5 py-1 rounded uppercase tracking-wider">
                      {course.level}
                    </span>
                    {course.isFree && (
                      <span className="bg-blue-500/5 text-blue-400 text-[10px] font-mono px-2.5 py-1 rounded border border-blue-500/20 uppercase tracking-wider">
                        Gratuit
                      </span>
                    )}
                  </div>
                  <h4 className="text-sm font-bold text-white leading-snug group-hover:text-blue-400 transition-colors duration-200 mb-8">{course.title}</h4>
                </div>
                
                <div className="space-y-4">
                  <div className="flex justify-between items-baseline">
                    <span className="text-[10px] font-mono text-slate-600 uppercase">Tarification universelle</span>
                    <p className="text-md font-mono font-bold text-white">
                      {course.isFree ? "0 FCFA" : `${course.price.toLocaleString()} FCFA`}
                    </p>
                  </div>
                  
                  {course.isFree ? (
                    <button
                      onClick={() => alert('Accès débloqué dans votre terminal de formation.')}
                      className="w-full bg-slate-900 border border-slate-800 hover:border-blue-500 hover:bg-blue-500 hover:text-slate-950 text-slate-300 font-mono text-[11px] font-bold py-2.5 rounded transition-all duration-300 uppercase tracking-wider"
                    >
                      Initialiser le cours
                    </button>
                  ) : (
                    <button
                      onClick={() => {
                        setSelectedCourse(course);
                        setPaymentMethod('');
                        setPaymentSuccess(false);
                      }}
                      className="w-full bg-blue-600 hover:bg-blue-500 text-slate-950 font-mono text-[11px] font-bold py-2.5 rounded transition-all duration-300 uppercase tracking-wider"
                    >
                      Acquérir la licence
                    </button>
                  )}
                </div>
              </div>
            ))}
        </div>
      </section>

      {/* MODAL DE PAIEMENT INTELLIGENT (Conçu comme un checkout de 2030) */}
      {selectedCourse && (
        <div className="fixed inset-0 bg-[#020617]/90 backdrop-blur-md flex items-center justify-center p-4 z-50 animate-fade-in">
          <div className="w-full max-w-md bg-slate-950 border border-slate-800 rounded-xl p-6 relative shadow-2xl">
            <button onClick={() => setSelectedCourse(null)} className="absolute top-4 right-4 text-slate-500 hover:text-white font-mono transition">ESC ✕</button>

            {!paymentSuccess ? (
              <>
                <div className="mb-6">
                  <span className="text-[9px] font-mono text-blue-500 tracking-widest uppercase">Secure Sandbox Checkout</span>
                  <h3 className="text-md font-bold text-white mt-1">Acquisition de module</h3>
                  <p className="text-xs text-slate-400 font-light mt-1">{selectedCourse.title}</p>
                </div>
                
                <div className="bg-[#020617] p-4 rounded-lg border border-slate-900 flex justify-between items-center mb-6">
                  <span className="text-xs font-mono text-slate-500 uppercase">Total Net :</span>
                  <span className="text-md font-mono font-bold text-blue-400">{selectedCourse.price.toLocaleString()} FCFA</span>
                </div>

                <form onSubmit={handlePayment} className="space-y-6">
                  <div className="grid grid-cols-2 gap-3">
                    {['mtn', 'wave', 'card', 'paypal'].map((method) => (
                      <button
                        key={method}
                        type="button"
                        onClick={() => setPaymentMethod(method)}
                        className={`p-3 rounded-lg border text-[10px] font-mono font-bold uppercase tracking-wider transition-all duration-200 ${paymentMethod === method ? 'border-blue-500 bg-blue-500/5 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.05)]' : 'border-slate-900 bg-[#020617] text-slate-400 hover:border-slate-800'}`}
                      >
                        {method === 'mtn' ? 'MTN MoMo' : method === 'wave' ? 'Wave' : method === 'card' ? 'Crypto / Card' : 'PayPal'}
                      </button>
                    ))}
                  </div>

                  {isProcessing ? (
                    <div className="w-full text-center py-3 bg-[#020617] border border-slate-900 rounded-lg text-[10px] font-mono text-slate-500 uppercase tracking-widest animate-pulse">
                      Vérification des blocs de sécurité...
                    </div>
                  ) : (
                    <button
                      type="submit"
                      disabled={!paymentMethod}
                      className={`w-full py-3 rounded-lg font-mono text-[11px] font-bold uppercase tracking-widest transition-all duration-300 ${paymentMethod ? 'bg-white text-slate-950 hover:bg-blue-500' : 'bg-slate-900 text-slate-600 cursor-not-allowed'}`}
                    >
                      Confirmer la transaction
                    </button>
                  )}
                </form>
              </>
            ) : (
              <div className="text-center py-8 space-y-4">
                <div className="w-12 h-12 rounded-full bg-blue-500/10 border border-blue-500/30 flex items-center justify-center text-blue-400 text-xl mx-auto shadow-[0_0_20px_rgba(59,130,246,0.1)]">✓</div>
                <div className="space-y-1">
                  <h3 className="text-md font-bold text-white uppercase tracking-wider font-mono">Licence Activée</h3>
                  <p className="text-xs text-slate-400 font-light">Le module est maintenant rattaché à votre signature numérique.</p>
                </div>
                <button onClick={() => setSelectedCourse(null)} className="w-full bg-slate-900 border border-slate-800 text-white font-mono text-[11px] font-bold py-2.5 rounded hover:border-blue-500 transition-colors duration-200 uppercase tracking-wider">
                  Accéder à l'infrastructure
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Home;
